/**
 * The set of naming-convention rules enforced by the linter.
 */
export enum NamingRule {
    /** Type declarations (concept, asset, participant, transaction, event, enum, scalar) must be camelCase. */
    TYPE_DECLARATION_CAMEL_CASE = 'type-declaration-camel-case',
    /** Properties (fields) in non-enum types must be PascalCase. */
    PROPERTY_PASCAL_CASE = 'property-pascal-case',
    /** Enum constants must be UPPER_SNAKE_CASE. */
    ENUM_CONSTANT_UPPER_SNAKE_CASE = 'enum-constant-upper-snake-case',
}

/**
 * A single naming-convention violation reported by the linter.
 */
export interface LintViolation {
    /** The identifier of the rule that was violated. */
    rule: NamingRule;
    /** The severity of the violation (0 = error, mirroring Spectral diagnostics). */
    severity: number;
    /** The offending identifier. */
    name: string;
    /** The metamodel `$class` of the offending node. */
    class: string;
    /** A human readable description of the violation. */
    message: string;
    /** The JSON path (as an array of keys) to the offending node within the AST. */
    path: Array<string | number>;
}

/** Matches an identifier that begins with an uppercase letter. */
const STARTS_WITH_UPPERCASE = /^[A-Z]/;

/** Matches a valid UPPER_SNAKE_CASE identifier, e.g. `RED`, `HOT_PINK`, `LEVEL_2`. */
const UPPER_SNAKE_CASE = /^[A-Z][A-Z0-9]*(_[A-Z0-9]+)*$/;

/**
 * Returns the short name of a metamodel `$class`, e.g.
 * `concerto.metamodel@1.0.0.EnumDeclaration` -> `EnumDeclaration`.
 * @param klass the fully qualified `$class` value
 * @returns the trailing type name
 */
function shortClassName(klass: unknown): string {
    if (typeof klass !== 'string') {
        return '';
    }
    const dot = klass.lastIndexOf('.');
    return dot === -1 ? klass : klass.substring(dot + 1);
}

/**
 * Determines whether a declaration is an enumeration.
 * @param declaration the declaration node
 * @returns true if the declaration is an EnumDeclaration
 */
function isEnumDeclaration(declaration: any): boolean {
    return shortClassName(declaration?.$class) === 'EnumDeclaration';
}

/**
 * Lints the properties (fields or enum constants) of a single declaration.
 * @param declaration the declaration node whose properties are linted
 * @param path the JSON path of the declaration within the AST
 * @param violations the accumulator of violations
 */
function lintProperties(declaration: any, path: Array<string | number>, violations: LintViolation[]): void {
    const properties = Array.isArray(declaration?.properties) ? declaration.properties : [];
    const enumeration = isEnumDeclaration(declaration);

    properties.forEach((property: any, index: number) => {
        const name = property?.name;
        if (typeof name !== 'string') {
            return;
        }
        const propertyPath = [...path, 'properties', index, 'name'];

        if (enumeration) {
            // Enum constants must be UPPER_SNAKE_CASE.
            if (!UPPER_SNAKE_CASE.test(name)) {
                violations.push({
                    rule: NamingRule.ENUM_CONSTANT_UPPER_SNAKE_CASE,
                    severity: 0,
                    name,
                    class: property.$class,
                    message: `Enum constant "${name}" should be UPPER_SNAKE_CASE.`,
                    path: propertyPath,
                });
            }
        } else {
            // Properties in non-enum types must be PascalCase (start with an uppercase letter).
            if (!STARTS_WITH_UPPERCASE.test(name)) {
                violations.push({
                    rule: NamingRule.PROPERTY_PASCAL_CASE,
                    severity: 0,
                    name,
                    class: property.$class,
                    message: `Property "${name}" should be PascalCase.`,
                    path: propertyPath,
                });
            }
        }
    });
}

/**
 * Lints a single declaration and its properties.
 * @param declaration the declaration node
 * @param path the JSON path of the declaration within the AST
 * @param violations the accumulator of violations
 */
function lintDeclaration(declaration: any, path: Array<string | number>, violations: LintViolation[]): void {
    const name = declaration?.name;
    if (typeof name === 'string') {
        // Type declarations must be camelCase (start with a lowercase letter).
        if (STARTS_WITH_UPPERCASE.test(name)) {
            violations.push({
                rule: NamingRule.TYPE_DECLARATION_CAMEL_CASE,
                severity: 0,
                name,
                class: declaration.$class,
                message: `Type declaration "${name}" should be camelCase.`,
                path: [...path, 'name'],
            });
        }
    }

    lintProperties(declaration, path, violations);
}

/**
 * Lints a single model node.
 * @param model the model node containing declarations
 * @param path the JSON path of the model within the AST
 * @param violations the accumulator of violations
 */
function lintModel(model: any, path: Array<string | number>, violations: LintViolation[]): void {
    const declarations = Array.isArray(model?.declarations) ? model.declarations : [];
    declarations.forEach((declaration: any, index: number) => {
        lintDeclaration(declaration, [...path, 'declarations', index], violations);
    });
}

/**
 * Lints a JSON-serialized Concerto model AST, reporting naming-convention
 * violations for type declarations, properties and enum constants.
 *
 * Naming rules enforced:
 * - Type declarations (concept, asset, participant, transaction, event, enum,
 *   scalar) must be camelCase.
 * - Properties (fields) in non-enum types must be PascalCase.
 * - Enum constants must be UPPER_SNAKE_CASE.
 *
 * @param ast a JSON-serialized Concerto model AST string
 * @returns a promise that resolves to the array of naming-convention violations
 */
export async function lintAST(ast: string): Promise<Array<any>> {
    const root = JSON.parse(ast);
    const violations: LintViolation[] = [];

    if (Array.isArray(root?.models)) {
        // A `Models` container with multiple models.
        root.models.forEach((model: any, index: number) => {
            lintModel(model, ['models', index], violations);
        });
    } else if (Array.isArray(root?.declarations)) {
        // A single `Model` node.
        lintModel(root, [], violations);
    }

    return violations;
}
